<template><div class="app-container">
 <el-form :inline="true"><el-form-item label="课题"><el-select v-model="topicId" filterable @change="reload" style="width:360px"><el-option v-for="t in topics" :key="t.topicId" :label="t.topicName" :value="t.topicId"/></el-select></el-form-item></el-form>
 <el-row :gutter="12" class="mb8" v-if="overview"><el-col :span="6"><el-card>课题总资金<br><b>{{money(overview.totalAmount)}}</b></el-card></el-col><el-col :span="6"><el-card>已到位<br><b>{{money(overview.arrivedAmount)}}</b></el-card></el-col><el-col :span="6"><el-card>已使用<br><b>{{money(overview.usedAmount)}}</b></el-card></el-col><el-col :span="6"><el-card>待拨资金<br><b>{{money(overview.pendingAllocationAmount)}}</b></el-card></el-col></el-row>
 <el-button class="mb8" type="primary" plain size="mini" icon="el-icon-plus" @click="openPlan()" v-hasPermi="['fund:use:add']" :disabled="!topicId">新增使用计划</el-button>
 <el-table :data="plans" v-loading="loading"><el-table-column label="使用名称" prop="useName" min-width="180"/><el-table-column label="计划金额" width="140"><template slot-scope="s">{{money(s.row.planAmount)}}</template></el-table-column><el-table-column label="责任人" prop="responsibleUserName"/><el-table-column label="计划时间" prop="planTime" width="165"/><el-table-column label="状态" width="90"><template slot-scope="s"><el-tag :type="s.row.status==='1'?'success':'warning'">{{s.row.status==='1'?'已结束':'执行中'}}</el-tag></template></el-table-column><el-table-column label="操作" width="280"><template slot-scope="s"><el-button type="text" @click="openRecords(s.row)">使用记录</el-button><el-button v-if="s.row.status==='0'" type="text" @click="openPlan(s.row)" v-hasPermi="['fund:use:edit']">编辑</el-button><el-button v-if="s.row.status==='0'" type="text" @click="finishPlan(s.row)" v-hasPermi="['fund:use:finish']">结束</el-button></template></el-table-column></el-table>
 <pagination v-show="total>0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="loadPlans"/>
 <el-dialog :title="planForm.usePlanId?'编辑使用计划':'新增使用计划'" :visible.sync="planOpen" width="620px"><el-form ref="planForm" :model="planForm" :rules="planRules" label-width="100px"><el-form-item label="使用名称" prop="useName"><el-input v-model="planForm.useName"/></el-form-item><el-form-item label="使用金额" prop="planAmount"><el-input-number v-model="planForm.planAmount" :min="0.01" :precision="2" :step="10000" style="width:100%"/></el-form-item><el-form-item label="责任人"><el-select v-model="planForm.responsibleUserId" clearable filterable style="width:100%"><el-option v-for="u in topicUsers" :key="u.userId" :label="u.nickName||u.userName" :value="u.userId"/></el-select></el-form-item><el-form-item label="计划时间"><el-date-picker v-model="planForm.planTime" type="datetime" value-format="yyyy-MM-dd HH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="资金说明"><el-input type="textarea" v-model="planForm.fundDesc"/></el-form-item></el-form><div slot="footer"><el-button @click="planOpen=false">取消</el-button><el-button type="primary" @click="savePlan">确定</el-button></div></el-dialog>
 <el-dialog :title="recordPlan.useName+' - 使用记录'" :visible.sync="recordsOpen" width="900px"><el-button v-if="recordPlan.status==='0'" type="primary" plain size="mini" @click="openRecord()" v-hasPermi="['fund:use:submit']">提交使用</el-button><el-table :data="records"><el-table-column label="名称" prop="useName"/><el-table-column label="金额" width="120"><template slot-scope="s">{{money(s.row.amount)}}</template></el-table-column><el-table-column label="提交人" prop="submitUserName"/><el-table-column label="时间" prop="useTime" width="165"/><el-table-column label="操作" width="120"><template slot-scope="s"><el-button v-if="recordPlan.status==='0'" type="text" @click="openRecord(s.row)">编辑</el-button><el-button v-if="recordPlan.status==='0'" type="text" @click="deleteRecord(s.row)">删除</el-button></template></el-table-column></el-table></el-dialog>
 <el-dialog title="使用记录" :visible.sync="recordOpen" width="600px"><el-form ref="recordForm" :model="recordForm" :rules="recordRules" label-width="100px"><el-form-item label="使用名称" prop="useName"><el-input v-model="recordForm.useName"/></el-form-item><el-form-item label="使用金额" prop="amount"><el-input-number v-model="recordForm.amount" :min="0.01" :precision="2" style="width:100%"/></el-form-item><el-form-item label="使用时间" prop="useTime"><el-date-picker v-model="recordForm.useTime" type="datetime" value-format="yyyy-MM-dd HH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="资金说明"><el-input type="textarea" v-model="recordForm.fundDesc"/></el-form-item><el-form-item label="使用凭证"><file-upload v-model="recordForm.voucherUrls" :limit="5" :fileType="['pdf','doc','docx','xls','xlsx','jpg','jpeg','png']"/></el-form-item></el-form><div slot="footer"><el-button @click="recordOpen=false">取消</el-button><el-button type="primary" @click="saveRecord">确定</el-button></div></el-dialog>
</div></template>
<script>
import {accessibleGroups,groupMembers} from '@/api/research/group';import {getOverview} from '@/api/fund/budget';import {listUsePlans,addUsePlan,updateUsePlan,listUseRecords,addUseRecord,updateUseRecord,delUseRecord,useFinishCheck,finishUse} from '@/api/fund/use';
export default{name:'FundUse',data(){return{topics:[],topicId:null,overview:null,plans:[],loading:false,total:0,query:{pageNum:1,pageSize:10},topicUsers:[],planOpen:false,planForm:{},recordsOpen:false,recordPlan:{},records:[],recordOpen:false,recordForm:{},planRules:{useName:[{required:true,message:'请输入使用名称'}],planAmount:[{required:true,message:'请输入金额'}]},recordRules:{useName:[{required:true,message:'请输入名称'}],amount:[{required:true,message:'请输入金额'}],useTime:[{required:true,message:'请选择时间'}]}}},created(){accessibleGroups().then(r=>{this.topics=(r.data||[]).map(g=>({topicId:g.groupId,topicName:g.groupName}));if(this.topics.length){this.topicId=this.topics[0].topicId;this.reload()}})},methods:{money(v){return Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:2})},reload(){this.loadPlans();this.loadTopicUsers();getOverview(this.topicId).then(r=>this.overview=r.data).catch(()=>this.overview=null)},loadPlans(){if(!this.topicId)return;this.loading=true;listUsePlans(Object.assign({},this.query,{topicId:this.topicId})).then(r=>{this.plans=r.rows;this.total=r.total;this.loading=false})},loadTopicUsers(){groupMembers(this.topicId).then(r=>{this.topicUsers=r.data||[]})},openPlan(row){this.planForm=row?Object.assign({},row):{topicId:this.topicId,useName:'',planAmount:0,responsibleUserId:null,planTime:null,fundDesc:''};this.planOpen=true},savePlan(){this.$refs.planForm.validate(ok=>{if(!ok)return;(this.planForm.usePlanId?updateUsePlan:addUsePlan)(this.planForm).then(()=>{this.$modal.msgSuccess('保存成功');this.planOpen=false;this.reload()})})},openRecords(row){this.recordPlan=row;listUseRecords(row.usePlanId).then(r=>{this.records=r.data||[];this.recordsOpen=true})},openRecord(row){this.recordForm=row?Object.assign({},row):{usePlanId:this.recordPlan.usePlanId,useName:'',amount:0,useTime:null,fundDesc:'',voucherUrls:''};this.recordOpen=true},saveRecord(){this.$refs.recordForm.validate(ok=>{if(!ok)return;(this.recordForm.useRecordId?updateUseRecord:addUseRecord)(this.recordForm).then(()=>{this.$modal.msgSuccess('保存成功');this.recordOpen=false;this.openRecords(this.recordPlan);this.reload()})})},deleteRecord(row){this.$modal.confirm('确认删除该使用记录？').then(()=>delUseRecord(row.useRecordId)).then(()=>{this.openRecords(this.recordPlan);this.reload()})},finishPlan(row){useFinishCheck(row.usePlanId).then(r=>{const c=r.data;const msg=!c.needConfirm?'实际使用金额与计划一致，确认结束？':(c.differenceAmount<0?'还有余额 '+Math.abs(c.differenceAmount)+' 元未使用，确认结束？':'实际使用超出计划 '+Math.abs(c.differenceAmount)+' 元，确认强制结束？');this.$modal.confirm(msg).then(()=>finishUse(row.usePlanId,c.needConfirm)).then(()=>{this.$modal.msgSuccess('计划已结束');this.reload()})})}}}
</script>
